import {descargarDocumento} from './documentos.js';
import {iniciarSelectoresBuscables} from './selectores.js';
iniciarSelectoresBuscables();
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const E=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={hoy:'<circle cx="12" cy="12" r="4"/><path d="M12 2v2m0 16v2M2 12h2m16 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2"/>',pedidos:'<rect x="5" y="4" width="14" height="17" rx="1"/><path d="M9 3h6v3H9zM9 11h6m-6 5h6"/>',semana:'<rect x="3" y="5" width="18" height="16" rx="1"/><path d="M7 3v4m10-4v4M3 11h18m-14 4h2m4 0h2"/>',calendario:'<rect x="3" y="5" width="18" height="16" rx="1"/><path d="M7 3v4m10-4v4M3 11h18M7 15h2m4 0h2m-8 3h2m4 0h2"/>',entregas:'<path d="M3 7h11v11H3zM14 11h4l3 4v3h-7"/><circle cx="7" cy="19" r="2"/><circle cx="17" cy="19" r="2"/>',entregados:'<path d="m5 12 4 4L19 6"/><path d="M20 12v8H4V4h9"/>',clientes:'<circle cx="12" cy="7" r="4"/><path d="M4 21v-3a8 8 0 0 1 16 0v3"/>',productos:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5m-9 5v9"/>',estadisticas:'<path d="M4 3v18h17M8 17v-5m5 5V7m5 10V4"/>',configuracion:'<path d="M4 5h16M4 12h16M4 19h16"/><circle cx="8" cy="5" r="2"/><circle cx="16" cy="12" r="2"/><circle cx="10" cy="19" r="2"/>',anulados:'<path d="M4 5h16M9 5V3h6v2M6 5l1 16h10l1-16M10 9v8m4-8v8"/>'};
const vistas=[['pedidos','Pedidos'],['hoy','Hoy'],['semana','Esta semana'],['calendario','Calendario'],['entregas','Para entregar'],['entregados','Entregados'],['presupuestos','Presupuestos'],['clientes','Clientes'],['productos','Productos'],['estadisticas','Estadísticas'],['anulados','Anulados'],['configuracion','Configuración']];
let datos=[],config,mesCalendario=C.fechaHoy().slice(0,7),filtroStats={modo:'todo',mes:C.fechaHoy().slice(0,7),desde:C.fechaHoy().slice(0,7)+'-01',hasta:C.fechaHoy()},busquedaStats='',vista='pedidos',filtros={},detalleId=null,instalable;
const clientes=()=>datos.filter(e=>e.tipo==='cliente'&&!e._oculto);const productos=()=>datos.filter(e=>e.tipo==='producto'&&!e._oculto);const pedidos=()=>datos.filter(e=>e.tipo==='pedido'&&!e._oculto);const buscar=id=>datos.find(e=>e.id===id);const cliente=p=>buscar(p.cliente)||{nombre:'Cliente no disponible',whatsapp:''};const opciones=(values,sel)=>values.map(v=>{const id=typeof v==='string'?v:v.id;return `<option value="${E(id)}" ${typeof v==='object'&&v.whatsapp?`data-busqueda="${E(v.whatsapp)}"`:''} ${id===sel?'selected':''}>${E(typeof v==='string'?v:v.nombre)}</option>`;}).join('');
const fecha=v=>v?new Date(v.slice(0,10)+'T12:00:00Z').toLocaleDateString('es-AR',{day:'2-digit',month:'2-digit',year:'numeric'}):'Sin fecha';const fechaHora=v=>new Date(v).toLocaleString('es-AR',{timeZone:'America/Argentina/Buenos_Aires',dateStyle:'short',timeStyle:'short'});
function toast(t){$('#toast').textContent=t;$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,4500);}function error(t){toast(t.message||t);}
function abrirModal(html){$('#modal-contenido').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();$('#modal').scrollTop=0;$('.cerrar')?.addEventListener('click',cerrarModal);}
function cerrarModal(){detalleId=null;$('#modal').close();}
const cabModal=t=>`<div class="modal-cabecera"><h2>${E(t)}</h2><button class="cerrar" aria-label="Cerrar">×</button></div>`;
async function cargar(){datos=await S.todas();config=buscar('config');}
async function guardar(entidad,mensaje){await S.guardar(entidad);await cargar();render();if(mensaje)toast(mensaje);sincronizar();}
const activo=p=>!p.anulado&&!p.presupuesto&&!C.entregado(p,config);const ordenar=ps=>ps.sort((a,b)=>(a.entrega||'9999').localeCompare(b.entrega||'9999')||a.numero-b.numero);
function recordatorios(){const hoy=C.fechaHoy();return ordenar(pedidos().filter(activo)).filter(p=>p.entrega&&p.entrega<=C.sumarDias(hoy,1)||new Date()-new Date(p.ultimoAvance||p.creado)>config.diasSinAvance*86400000);}
function render(){vista=location.hash.slice(1).split('?')[0]||'pedidos';if(!vistas.some(v=>v[0]===vista))vista='pedidos';$('#titulo').textContent=vistas.find(v=>v[0]===vista)[1];$('#fecha').textContent=new Date().toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',timeZone:'America/Argentina/Buenos_Aires'});$('#navegacion').innerHTML=vistas.map(([id,label],i)=>`${i===7?'<div class="separador"></div>':''}<a href="#${id}" class="${vista===id?'activo':''}" ${vista===id?'aria-current="page"':''}><svg viewBox="0 0 24 24" aria-hidden="true">${icons[id]||icons.pedidos}</svg>${label}</a>`).join('');$('#nuevo').textContent=vista==='presupuestos'?'＋ Nuevo presupuesto':'＋ Nuevo pedido';const conflicts=datos.filter(e=>e._conflicto);$('#aviso').innerHTML=conflicts.length?`<div class="aviso error">Hay ${conflicts.length} cambio(s) realizados en dos dispositivos. <button class="apertura" id="conflictos">Revisar cambios</button></div>`:'';$('#conflictos')?.addEventListener('click',mostrarConflictos);
 if(['hoy','pedidos','semana','entregas','entregados','presupuestos','anulados'].includes(vista))renderPedidos();if(vista==='calendario')renderCalendario();if(vista==='clientes')renderClientes();if(vista==='productos')renderProductos();if(vista==='estadisticas')renderEstadisticas();if(vista==='configuracion')renderConfiguracion();}
function grupoPedidos(){let ps=pedidos();const hoy=C.fechaHoy();if(vista==='entregados')ps=ps.filter(p=>!p.anulado&&!p.presupuesto&&C.entregado(p,config));else if(vista==='anulados')ps=ps.filter(p=>p.anulado);else if(vista==='presupuestos')ps=ps.filter(p=>p.presupuesto&&!p.anulado);else{ps=ps.filter(activo);if(vista==='hoy')ps=ps.filter(p=>p.entrega&&p.entrega<=C.sumarDias(hoy,1));if(vista==='semana'){const start=C.inicioSemana();ps=ps.filter(p=>p.entrega>=start&&p.entrega<=C.sumarDias(start,6));}if(vista==='entregas')ps=ps.filter(p=>C.indiceEstado(p,config)>=config.estados.length-2);}
 if(filtros.buscar){const q=filtros.buscar.toLowerCase();ps=ps.filter(p=>[p.numero,'#'+p.numero,cliente(p).nombre,cliente(p).whatsapp,...p.items.map(i=>i.nombre)].join(' ').toLowerCase().includes(q));}if(filtros.fecha)ps=ps.filter(p=>p.entrega===filtros.fecha);if(filtros.producto)ps=ps.filter(p=>p.items.some(i=>i.producto===filtros.producto));if(filtros.pago)ps=ps.filter(p=>C.estadoPago(p)===filtros.pago);if(filtros.entrega)ps=ps.filter(p=>p.formaEntrega===filtros.entrega);if(filtros.canal)ps=ps.filter(p=>p.canal===filtros.canal);return ordenar(ps);}
function renderPedidos(){const ps=grupoPedidos(),hoy=C.fechaHoy(),aps=pedidos().filter(activo);let resumen='';if(vista==='hoy')resumen=`<div class="resumen">${[['Atrasados',aps.filter(p=>p.entrega&&p.entrega<hoy).length,'atrasados'],['Para hoy',aps.filter(p=>p.entrega===hoy).length,'hoy'],['Para mañana',aps.filter(p=>p.entrega===C.sumarDias(hoy,1)).length,'mañana'],['En marcha',aps.length,'pedidos']].map(([t,n,id])=>`<button class="indicador ${id==='atrasados'&&n?'alerta':''}" data-resumen="${id}"><span class="texto">${t}</span><span class="valor">${n}</span></button>`).join('')}</div>`;
 const filtrosHTML=`<div class="filtros"><div class="campo busqueda"><label for="buscar">Buscar</label><input id="buscar" type="search" placeholder="Cliente, WhatsApp, pedido o producto" value="${E(filtros.buscar||'')}"></div><div class="campo"><label for="filtrar-fecha">Entrega</label><input id="filtrar-fecha" type="date" value="${E(filtros.fecha||'')}"></div><button class="boton" id="mas-filtros">Filtros${Object.keys(filtros).filter(k=>!['buscar','fecha'].includes(k)&&filtros[k]).length?' · activos':''}</button>${Object.values(filtros).some(Boolean)?'<button class="boton-discreto" id="limpiar-filtros">Limpiar</button>':''}</div>`;
 const atrasados=aps.filter(p=>p.entrega&&p.entrega<hoy).length;$('#contenido').innerHTML=resumen+`<div class="panel"><div class="panel-cabecera"><h2>${vista==='hoy'?'Próximas entregas':E(vistas.find(v=>v[0]===vista)[1])}</h2><span class="subtle">${ps.length} ${ps.length===1?'pedido':'pedidos'}</span></div>${vista==='hoy'?'<p class="subtle">Atrasados, hoy y mañana, en orden de entrega.</p>':vista==='pedidos'?'<p class="subtle">Todos los pedidos pendientes, agrupados por día de entrega.</p>':''}${filtrosHTML}<div id="tabla-pedidos">${listadoPedidos(ps)}</div></div>`+(vista==='hoy'&&recordatorios().some(p=>!p.entrega||p.entrega>C.sumarDias(hoy,1))?`<div class="panel"><h2>Pedidos sin avance</h2>${tablaPedidos(recordatorios().filter(p=>!p.entrega||p.entrega>C.sumarDias(hoy,1)))}</div>`:'');
 $('#buscar').addEventListener('input',e=>{filtros.buscar=e.target.value;$('#tabla-pedidos').innerHTML=listadoPedidos(grupoPedidos());bindPedidos();});$('#filtrar-fecha').addEventListener('change',e=>{filtros.fecha=e.target.value;render();});$('#mas-filtros').onclick=modalFiltros;$('#limpiar-filtros')?.addEventListener('click',()=>{filtros={};render();});$$('[data-resumen]').forEach(b=>b.onclick=()=>{const id=b.dataset.resumen;filtros={};if(id==='pedidos')location.hash='#pedidos';else{vista='hoy';const subset=ordenar(aps.filter(p=>id==='atrasados'?p.entrega&&p.entrega<hoy:p.entrega===C.sumarDias(hoy,id==='mañana'?1:0)));$('#tabla-pedidos').innerHTML=tablaPedidos(subset);bindPedidos();}});bindPedidos();}
function listadoPedidos(ps){
 if(vista!=='pedidos'||!ps.length)return tablaPedidos(ps);
 const grupos=new Map();
 for(const p of ps){const dia=p.entrega||'';if(!grupos.has(dia))grupos.set(dia,[]);grupos.get(dia).push(p);}
 const hoy=C.fechaHoy();
 return [...grupos].map(([dia,grupo])=>{
  const etiqueta=!dia?'Sin fecha de entrega':new Date(dia+'T12:00:00Z').toLocaleDateString('es-AR',{weekday:'long',day:'numeric',month:'long',year:'numeric',timeZone:'America/Argentina/Buenos_Aires'});
  const aviso=dia&&dia<hoy?'Atrasados':dia===hoy?'Hoy':dia===C.sumarDias(hoy,1)?'Mañana':'';
  const id='entrega-'+(dia||'sin-fecha');
  return `<section class="grupo-entrega" data-fecha="${E(dia)}" aria-labelledby="${id}"><div class="grupo-entrega-cabecera"><h3 id="${id}">${E(etiqueta)}</h3><div class="grupo-entrega-info">${aviso?`<span class="chip ${dia<hoy?'atrasado':dia===hoy?'hoy':'mañana'}">${aviso}</span>`:''}<span class="subtle">${grupo.length} ${grupo.length===1?'pedido':'pedidos'}</span></div></div>${tablaPedidos(grupo,true)}</section>`;
 }).join('');
}
function tablaPedidos(ps,agrupados=false){if(!ps.length)return `<div class="vacio"><strong>No hay pedidos en esta vista</strong>${pedidos().length?'Probá otra fecha o quitá los filtros.':'Cargá el primero para empezar a organizar las entregas.'}${!pedidos().length?'<br><button class="boton principal primer-pedido">＋ Nuevo pedido</button>':''}</div>`;return `<div class="tabla-contenedor"><table class="tabla tabla-pedidos"><thead><tr><th>Pedido / cliente</th><th class="col-productos">Productos</th><th>Entrega</th><th>Estado</th><th class="col-importe">Importe</th><th class="col-cobro">Cobro</th></tr></thead><tbody>${ps.map(p=>{const c=cliente(p),u=C.urgencia(p),idx=C.indiceEstado(p,config);return `<tr><td><button class="abrir" data-pedido="${E(p.id)}"><span class="pedido-identidad"><span class="numero">#${p.numero}</span> <span class="cliente" title="${E(c.nombre)}">${E(c.nombre)}</span></span><span class="secundario">${E(c.whatsapp)}</span></button>${p.etiquetas?.length?`<div class="etiquetas">${p.etiquetas.map(t=>`<span class="chip">${E(t)}</span>`).join('')}</div>`:''}</td><td class="col-productos"><span>${p.items.reduce((s,i)=>s+i.cantidad,0)} ${p.items.length===1?E(p.items[0].unidad||'unidad')+'(s)':'unidades / planchas'}</span><span class="secundario resumen-productos" title="${E(p.items.map(i=>i.nombre).join(' · '))}">${p.items.map(i=>E(i.nombre)).join(' · ')}</span></td><td>${agrupados?`<span title="Entrega: ${fecha(p.entrega)}">${E(p.formaEntrega)}</span>`:`<span class="chip ${C.entregado(p,config)?'verde':u}">${C.entregado(p,config)?fecha(p.entregadoEn||p.entrega):u==='hoy'?'Hoy':u==='mañana'?'Mañana':fecha(p.entrega)}</span>${u==='atrasado'&&!C.entregado(p,config)?'<span class="secundario">Atrasado</span>':''}<span class="secundario">${E(p.formaEntrega)}</span>`}</td><td><span class="estado-pedido" title="${E(p.anulado?'Anulado':p.presupuesto?'Presupuesto':C.estadoGeneral(p,config))}">${E(p.anulado?'Anulado':p.presupuesto?'Presupuesto':C.estadoGeneral(p,config))}</span>${!p.anulado&&!p.presupuesto?`<div class="progreso" aria-hidden="true">${config.estados.map((_,i)=>`<i class="${i<=idx?'hecho':''}"></i>`).join('')}</div>`:''}</td><td class="importe" title="${E(C.pesos(C.total(p)))}">${C.pesos(C.total(p))}</td><td class="col-cobro"><span class="chip ${C.estadoPago(p)==='Cobrado'?'verde':''}">${C.estadoPago(p)}</span><span class="secundario">${C.pesos(C.cobrado(p))}</span></td></tr>`;}).join('')}</tbody></table></div>`;}
function bindPedidos(){$$('[data-pedido]').forEach(b=>b.onclick=()=>mostrarPedido(b.dataset.pedido));$$('.primer-pedido').forEach(b=>b.onclick=()=>formPedido());}
function modalFiltros(){abrirModal(cabModal('Filtrar pedidos')+`<form id="form-filtros"><div class="grilla">${[['producto','Producto',productos()],['pago','Cobro',['Sin cobrar','Cobro parcial','Cobrado']],['entrega','Forma de entrega',['Retira','Encuentro','Llevo']],['canal','Canal',config.canales]].map(([k,l,vs])=>`<div class="campo"><label for="f-${k}">${l}</label><select id="f-${k}" name="${k}"><option value="">Todos</option>${opciones(vs,filtros[k])}</select></div>`).join('')}</div><div class="modal-pie"><button class="boton principal">Aplicar</button></div></form>`);$('#form-filtros').onsubmit=e=>{e.preventDefault();Object.assign(filtros,Object.fromEntries(new FormData(e.target)));cerrarModal();render();};}
function formularioCliente(c={},inline=false){return `<div class="grilla"><div class="campo"><label for="c-nombre">Nombre *</label><input id="c-nombre" name="nombre" required value="${E(c.nombre||'')}" maxlength="150"></div><div class="campo"><label for="c-wpp">WhatsApp *</label><input id="c-wpp" name="whatsapp" type="tel" required placeholder="11 1234 5678" value="${E(c.whatsapp||'')}" maxlength="30"><small>Con código de área. Para otros países, incluí el código de país.</small></div><div class="campo"><label for="c-entrega">Entrega habitual</label><select id="c-entrega" name="formaEntrega">${opciones(['Retira','Encuentro','Llevo'],c.formaEntrega||'Retira')}</select></div><div class="campo"><label for="c-direccion">Dirección / punto de encuentro</label><input id="c-direccion" name="direccion" value="${E(c.direccion||'')}" maxlength="300"></div><div class="campo ancho"><label for="c-notas">Notas del cliente</label><textarea id="c-notas" name="notas" maxlength="3000">${E(c.notas||'')}</textarea></div></div>`;}
function leerCliente(form,id){const f=Object.fromEntries(new FormData(form));const w=f.whatsapp.trim();if(w.replace(/\D/g,'').length<8)throw Error('Revisá el número de WhatsApp.');return {tipo:'cliente',id:id||crypto.randomUUID(),nombre:f.nombre.trim(),whatsapp:w,formaEntrega:f.formaEntrega,direccion:f.direccion.trim(),notas:f.notas.trim()};}
function formCliente(id,onDone){
 const c=id?buscar(id):{};
 abrirModal(cabModal(id?'Editar cliente':'Nuevo cliente')+`<form id="form-cliente">${formularioCliente(c)}<div id="duplicado-cliente" role="status" hidden></div><div class="modal-pie"><button class="boton principal">Guardar cliente</button></div></form>`);
 const revisar=()=>{
  const repetidos=C.clientesDuplicados(clientes(),$('#c-wpp').value,id),aviso=$('#duplicado-cliente');
  aviso.hidden=!repetidos.length;aviso.className='aviso aviso-duplicado';
  aviso.innerHTML=repetidos.length?`<strong>Este WhatsApp ya está registrado.</strong>${repetidos.map(c=>`<div class="duplicado-opcion"><span>${E(c.nombre)} · ${E(c.whatsapp)}</span><button type="button" class="apertura" data-usar-cliente="${E(c.id)}">${onDone?'Usar este cliente':'Ver cliente existente'}</button></div>`).join('')}`:'';
  $$('[data-usar-cliente]').forEach(b=>b.onclick=()=>{cerrarModal();if(onDone)onDone(b.dataset.usarCliente);else mostrarCliente(b.dataset.usarCliente);});
  return repetidos;
 };
 $('#c-wpp').addEventListener('input',revisar);revisar();
 $('#form-cliente').onsubmit=async e=>{
  e.preventDefault();const boton=e.submitter;
  try{const obj=leerCliente(e.target,id),repetidos=revisar();if(repetidos.length&&!confirm(`Ya existe ${repetidos.map(c=>c.nombre).join(', ')} con este WhatsApp. ¿Querés guardar otro cliente con el mismo número?`))return;
   if(boton)boton.disabled=true;await guardar(obj,'Cliente guardado');cerrarModal();if(onDone)onDone(obj.id);
  }catch(err){error(err);}finally{if(boton)boton.disabled=false;}
 };
}
function nuevoPedidoPara(clienteId='',entrega=''){
 const c=buscar(clienteId);
 formPedido(null,false,{cliente:clienteId,entrega,formaEntrega:c?.formaEntrega||'Retira',direccion:c?.direccion||'',canal:'WhatsApp',etiquetas:[],notas:'',items:[],pagos:[],descuento:0,presupuesto:false});
}
function formPedido(id,presupuesto=vista==='presupuestos',draft){const existente=id?buscar(id):null;let p=structuredClone(draft||existente||{cliente:'',entrega:'',formaEntrega:'Retira',direccion:'',canal:'WhatsApp',etiquetas:[],notas:'',items:[],pagos:[],descuento:0,presupuesto});const productosActivos=productos().filter(p=>p.activo);if(!p.items.length&&productosActivos.length){const prod=productosActivos[0];p.items.push({id:crypto.randomUUID(),producto:prod.id,nombre:prod.nombre,unidad:prod.unidad,cantidad:1,precio:prod.precio,costo:prod.costo,estado:config.estados[0].id});}const lineas=()=>p.items.map((i,k)=>`<div class="linea-producto" data-linea="${k}"><div class="campo"><label for="i-prod-${k}">Producto</label><select id="i-prod-${k}" data-prop="producto">${opciones(productos().filter(x=>x.activo||x.id===i.producto),i.producto)}</select></div><div class="campo"><label for="i-cant-${k}">${E(i.unidad==='plancha'?'Planchas':'Cantidad')}</label><input id="i-cant-${k}" data-prop="cantidad" type="number" min="1" step="1" required value="${i.cantidad}"></div><div class="campo"><label for="i-precio-${k}">Precio / ${E(i.unidad||'u.')}</label><input id="i-precio-${k}" data-prop="precio" type="number" min="0" step="0.01" required value="${i.precio/100}"></div><div class="campo"><label for="i-costo-${k}">Costo / ${E(i.unidad||'u.')}</label><input id="i-costo-${k}" data-prop="costo" type="number" min="0" step="0.01" required value="${i.costo/100}"></div><button class="eliminar" type="button" data-quitar="${k}" aria-label="Quitar ${E(i.nombre)}">×</button></div>`).join('');
 abrirModal(cabModal(existente?`Editar ${p.presupuesto?'presupuesto':'pedido'} #${p.numero}`:p.presupuesto?'Nuevo presupuesto':'Nuevo pedido')+`<form id="form-pedido"><div class="grilla"><div class="campo ancho"><label for="p-cliente">Cliente *</label><select id="p-cliente" name="cliente" required><option value="">Elegí un cliente</option>${opciones(clientes().sort((a,b)=>a.nombre.localeCompare(b.nombre)),p.cliente)}</select><button type="button" id="cliente-nuevo" class="apertura">＋ Crear cliente</button></div><div class="campo"><label for="p-fecha">Fecha de entrega</label><input id="p-fecha" name="entrega" type="date" value="${E(p.entrega)}"><small>Podés dejarla vacía mientras sea un posible pedido.</small></div><div class="campo"><label for="p-canal">Canal de venta</label><select id="p-canal" name="canal">${opciones(config.canales,p.canal)}</select></div><div class="campo"><label for="p-forma">Forma de entrega</label><select id="p-forma" name="formaEntrega">${opciones(['Retira','Encuentro','Llevo'],p.formaEntrega)}</select></div><div class="campo"><label for="p-direccion">Dirección / lugar de encuentro</label><input id="p-direccion" name="direccion" value="${E(p.direccion)}" maxlength="300"></div></div><div class="seccion-formulario"><h3>Productos</h3><div id="lineas">${lineas()}</div><button type="button" class="boton" id="agregar-producto" ${!productosActivos.length?'disabled':''}>＋ Agregar producto</button><div class="total-formulario"><div class="campo"><label for="p-descuento">Descuento ($)</label><input id="p-descuento" name="descuento" type="number" min="0" step="0.01" value="${(p.descuento||0)/100}"></div><div>Total <span id="total-formulario">${C.pesos(C.total(p))}</span></div></div></div><div class="seccion-formulario"><h3>Etiquetas</h3><div class="checklist">${[...new Set([...config.etiquetas,...(p.etiquetas||[])])].map(t=>`<label><input type="checkbox" name="etiquetas" value="${E(t)}" ${p.etiquetas.includes(t)?'checked':''}> ${E(t)}</label>`).join('')}</div><div class="campo" style="margin-top:16px"><label for="p-notas">Observaciones del pedido</label><textarea id="p-notas" name="notas" maxlength="5000">${E(p.notas)}</textarea></div></div>${!existente&&!p.presupuesto?`<div class="seccion-formulario"><h3>Cobro inicial (opcional)</h3><div class="grilla"><div class="campo"><label for="p-cobro">Monto cobrado ($)</label><input id="p-cobro" name="cobro" type="number" min="0" step="0.01" value="${p.cobro||0}"></div><div class="campo"><label for="p-metodo">Método</label><select id="p-metodo" name="metodo">${opciones(['Efectivo','Transferencia'],p.metodo)}</select></div></div></div>`:''}<div class="modal-pie"><button class="boton principal">${existente?'Guardar cambios':p.presupuesto?'Crear presupuesto':'Crear pedido'}</button></div></form>`);
 const recoger=()=>{const f=Object.fromEntries(new FormData($('#form-pedido')));Object.assign(p,{cliente:f.cliente,entrega:f.entrega,canal:f.canal,formaEntrega:f.formaEntrega,direccion:f.direccion.trim(),notas:f.notas.trim(),descuento:C.centavos(f.descuento),etiquetas:new FormData($('#form-pedido')).getAll('etiquetas'),cobro:f.cobro,metodo:f.metodo});return p;};
 function bindLineas(){$$('[data-linea]').forEach(row=>{const k=+row.dataset.linea;row.querySelectorAll('[data-prop]').forEach(input=>input.addEventListener('input',()=>{try{const key=input.dataset.prop;if(key==='producto'){const prod=buscar(input.value);Object.assign(p.items[k],{producto:prod.id,nombre:prod.nombre,unidad:prod.unidad,precio:prod.precio,costo:prod.costo});$('#lineas').innerHTML=lineas();bindLineas();}else p.items[k][key]=key==='cantidad'?Number(input.value):C.centavos(input.value);$('#total-formulario').textContent=C.pesos(C.total(p));}catch{}}));});$$('[data-quitar]').forEach(b=>b.onclick=()=>{p.items.splice(+b.dataset.quitar,1);$('#lineas').innerHTML=lineas();bindLineas();$('#total-formulario').textContent=C.pesos(C.total(p));});}bindLineas();
 $('#agregar-producto').onclick=()=>{const prod=productosActivos[0];p.items.push({id:crypto.randomUUID(),producto:prod.id,nombre:prod.nombre,unidad:prod.unidad,cantidad:1,precio:prod.precio,costo:prod.costo,estado:config.estados[0].id});$('#lineas').innerHTML=lineas();bindLineas();$('#total-formulario').textContent=C.pesos(C.total(p));};$('#p-descuento').oninput=e=>{try{p.descuento=C.centavos(e.target.value);$('#total-formulario').textContent=C.pesos(C.total(p));}catch{}};$('#p-cliente').onchange=e=>{const c=buscar(e.target.value);if(c){$('#p-forma').value=c.formaEntrega;$('#p-forma').dispatchEvent(new Event('change',{bubbles:true}));$('#p-direccion').value=c.direccion;}};$('#cliente-nuevo').onclick=()=>{try{recoger();formCliente(null,newId=>{p.cliente=newId;const c=buscar(newId);p.formaEntrega=c.formaEntrega;p.direccion=c.direccion;formPedido(id,p.presupuesto,p);});}catch(err){error(err);}};
 $('#form-pedido').onsubmit=async e=>{e.preventDefault();try{recoger();C.validarPedido(p);const now=new Date().toISOString();const inicial=!existente;const cobroInicial=inicial&&!p.presupuesto?C.centavos(p.cobro||0):0;if(cobroInicial>C.total(p)&&!confirm('El cobro supera el total del pedido. ¿Querés registrarlo igual?'))return;const obj={...p,id:existente?.id||crypto.randomUUID(),tipo:'pedido',numero:existente?.numero||await S.numeroNuevo(),creado:existente?.creado||now,ultimoAvance:existente?.ultimoAvance||existente?.creado||now,anulado:existente?.anulado||false,pagos:existente?.pagos||[],historial:[...(existente?.historial||[]),{fecha:now,texto:inicial?'Pedido creado':'Datos del pedido editados'}]};delete obj.cobro;delete obj.metodo;if(!C.entregado(obj,config))obj.entregadoEn=null;if(cobroInicial)obj.pagos.push({id:crypto.randomUUID(),monto:cobroInicial,fecha:C.fechaHoy(),metodo:p.metodo});await guardar(obj,inicial?'Guardado':'Cambios guardados');mostrarPedido(obj.id);}catch(err){error(err);}};
}
async function cambiarEstado(id,itemId,estado){
 $$('[data-estado-item]').forEach(sel=>sel.disabled=true);
 try{const p=structuredClone(buscar(id));const item=p.items.find(i=>i.id===itemId);const anterior=config.estados.find(e=>e.id===item.estado)?.nombre||'';const siguiente=config.estados.find(e=>e.id===estado).nombre;item.estado=estado;const now=new Date().toISOString();p.ultimoAvance=now;p.historial.push({fecha:now,texto:`${item.nombre}: ${anterior} → ${siguiente}`});if(!p.confirmadoEn&&C.indiceEstado(p,config)>0)p.confirmadoEn=now;if(C.entregado(p,config)&&!p.entregadoEn)p.entregadoEn=now;if(!C.entregado(p,config))p.entregadoEn=null;await guardar(p,'Estado actualizado');mostrarPedido(id);}
 finally{$$('[data-estado-item]').forEach(sel=>sel.disabled=false);}
}
function mostrarPedido(id){const p=buscar(id);if(!p)return;detalleId=id;const c=cliente(p);abrirModal(cabModal(`${p.presupuesto?'Presupuesto':'Pedido'} #${p.numero}`)+`<div class="panel-cabecera"><div><h3>${E(c.nombre)}</h3><span class="subtle">${E(c.whatsapp)}</span></div><a class="boton" target="_blank" rel="noopener noreferrer" href="${E(C.whatsapp(c.whatsapp))}">WhatsApp</a></div><div class="grilla"><div><span class="subtle">Entrega</span><p>${fecha(p.entrega)} · ${E(p.formaEntrega)}${p.direccion?'<br>'+E(p.direccion):''}</p>${C.mapa(p.direccion)?`<a class="boton boton-pequeno" target="_blank" rel="noopener noreferrer" href="${E(C.mapa(p.direccion))}">Ver en mapa</a>`:''}</div><div><span class="subtle">Ingreso</span><p>${fechaHora(p.creado)}<br><span class="chip">${E(p.canal)}</span></p></div></div><div class="detalle-resumen"><div><span class="subtle">Total</span><strong>${C.pesos(C.total(p))}</strong></div><div><span class="subtle">Cobrado</span><strong>${C.pesos(C.cobrado(p))}</strong></div><div><span class="subtle">Saldo</span><strong>${C.pesos(C.saldo(p))}</strong></div></div>${C.cobrado(p)>C.total(p)?`<p class="aviso-linea">Cobro excedente: ${C.pesos(C.cobrado(p)-C.total(p))}.</p>`:''}<div class="fila-acciones"><button class="boton" id="editar-pedido">${p.presupuesto?'Editar presupuesto':'Editar pedido'}</button>${p.presupuesto?'<button class="boton principal" id="confirmar-presupuesto">Convertir en pedido</button>':''}<button class="boton" data-documento="presupuesto">Presupuesto PDF</button>${!p.presupuesto?'<button class="boton" data-documento="comprobante">Comprobante PDF</button>':''}<button class="boton" data-documento="etiqueta">Etiqueta PDF</button></div><div class="seccion-formulario"><h3>Productos · ${E(C.estadoGeneral(p,config))}</h3>${p.items.map(i=>`<div class="detalle-item"><div><strong>${E(i.nombre)}</strong><span class="subtle">${i.cantidad} ${E(i.unidad||'unidad')}(s) × ${C.pesos(i.precio)} = ${C.pesos(i.cantidad*i.precio)}</span></div>${!p.presupuesto&&!p.anulado?`<select class="control" data-estado-item="${E(i.id)}" aria-label="Estado de ${E(i.nombre)}">${opciones(config.estados,i.estado)}</select>`:`<span class="chip">${E(config.estados.find(e=>e.id===i.estado)?.nombre)}</span>`}</div>`).join('')}${p.descuento?`<p class="subtle">Descuento: ${C.pesos(p.descuento)}</p>`:''}</div>${!p.presupuesto?`<div class="seccion-formulario"><h3>Cobros · ${C.estadoPago(p)}</h3><div class="pagos-lista">${p.pagos.map(pay=>`<div class="pago"><span>${fecha(pay.fecha)} · ${E(pay.metodo)}</span><span class="importe">${C.pesos(pay.monto)} ${!p.anulado?`<button class="boton-discreto" data-borrar-pago="${E(pay.id)}">Anular cobro</button>`:''}</span></div>`).join('')||'<p class="subtle">Sin cobros registrados.</p>'}</div>${!p.anulado?`<form id="form-cobro" class="cobro-form"><div class="campo"><label for="cobro-monto">Monto ($)</label><input id="cobro-monto" name="monto" type="number" min="0.01" step="0.01" required></div><div class="campo"><label for="cobro-fecha">Fecha</label><input id="cobro-fecha" name="fecha" type="date" required value="${C.fechaHoy()}"></div><div class="campo"><label for="cobro-metodo">Método</label><select id="cobro-metodo" name="metodo">${opciones(['Efectivo','Transferencia'])}</select></div><button class="boton principal">Cargar cobro</button></form>`:''}</div>`:''}${p.notas||c.notas?`<div class="seccion-formulario"><h3>Observaciones</h3>${p.notas?`<p class="texto-notas">${E(p.notas)}</p>`:''}${c.notas?`<p class="subtle texto-notas">Cliente: ${E(c.notas)}</p>`:''}</div>`:''}<div class="seccion-formulario"><h3>Historial</h3><ul class="historial">${[...(p.historial||[])].reverse().map(h=>`<li>${E(h.texto)}<time>${fechaHora(h.fecha)}</time></li>`).join('')}</ul></div><div class="modal-pie">${p._anterior?'<button class="boton" id="deshacer-pedido">Deshacer último cambio</button>':''}${p.anulado?'<button class="boton" id="restaurar-pedido">Restaurar pedido</button>':'<button class="boton peligro" id="anular-pedido">Anular pedido</button>'}</div>`);
 $('#editar-pedido').onclick=()=>formPedido(id);$$('[data-estado-item]').forEach(sel=>sel.onchange=()=>cambiarEstado(id,sel.dataset.estadoItem,sel.value).catch(error));$$('[data-documento]').forEach(b=>b.onclick=()=>descargarDocumento(b.dataset.documento,p,c,config).catch(error));$('#confirmar-presupuesto')?.addEventListener('click',async()=>{const obj=structuredClone(p);obj.presupuesto=false;obj.confirmadoEn=new Date().toISOString();obj.ultimoAvance=obj.confirmadoEn;obj.items.forEach(i=>i.estado=config.estados[1].id);obj.historial.push({fecha:new Date().toISOString(),texto:'Presupuesto convertido en pedido confirmado'});await guardar(obj,'Pedido confirmado');mostrarPedido(id);});$('#form-cobro')?.addEventListener('submit',async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),monto=C.centavos(f.monto);if(monto<=0)throw Error('El cobro debe ser mayor a cero.');if(C.cobrado(p)+monto>C.total(p)&&!confirm('El cobro acumulado supera el total. ¿Querés registrarlo igual?'))return;const obj=structuredClone(p);obj.pagos.push({id:crypto.randomUUID(),monto,fecha:f.fecha,metodo:f.metodo});obj.historial.push({fecha:new Date().toISOString(),texto:`Cobro registrado: ${C.pesos(monto)} · ${f.metodo}`});await guardar(obj,'Cobro registrado');mostrarPedido(id);}catch(err){error(err);}});$$('[data-borrar-pago]').forEach(b=>b.onclick=async()=>{if(!confirm('¿Anular este cobro? Quedará registrado en el historial.'))return;const obj=structuredClone(p);const pay=obj.pagos.find(x=>x.id===b.dataset.borrarPago);obj.pagos=obj.pagos.filter(x=>x.id!==pay.id);obj.historial.push({fecha:new Date().toISOString(),texto:`Cobro anulado: ${C.pesos(pay.monto)} · ${pay.metodo}`});await guardar(obj,'Cobro anulado');mostrarPedido(id);});$('#deshacer-pedido')?.addEventListener('click',async()=>{if(!confirm('¿Recuperar la versión anterior del pedido?'))return;await S.deshacer(id);await cargar();render();mostrarPedido(id);toast('Último cambio deshecho');sincronizar();});$('#anular-pedido')?.addEventListener('click',()=>anularPedido(id));$('#restaurar-pedido')?.addEventListener('click',async()=>{if(!confirm('¿Restaurar este pedido? Volverá a sus vistas y estadísticas.'))return;const obj=structuredClone(p);obj.anulado=false;obj.historial.push({fecha:new Date().toISOString(),texto:'Pedido restaurado'});await guardar(obj,'Pedido restaurado');mostrarPedido(id);});}
function anularPedido(id){abrirModal(cabModal('Anular pedido')+`<p>El pedido quedará recuperable en Anulados y no contará en ninguna estadística.</p><form id="form-anular"><div class="campo"><label for="motivo">Motivo</label><select id="motivo" name="motivo">${opciones(['Cancelado por cliente','No respondió','Error de carga','Otro'])}</select></div><div class="campo" style="margin-top:15px"><label for="detalle-anulacion">Detalle (opcional)</label><textarea id="detalle-anulacion" name="detalle"></textarea></div><div class="modal-pie"><button class="boton peligro">Confirmar anulación</button></div></form>`);$('#form-anular').onsubmit=async e=>{e.preventDefault();const f=Object.fromEntries(new FormData(e.target)),p=structuredClone(buscar(id));p.anulado=true;p.motivoAnulacion=f.motivo;p.historial.push({fecha:new Date().toISOString(),texto:'Anulado: '+f.motivo+(f.detalle?' · '+f.detalle:'')});await guardar(p,'Pedido anulado');cerrarModal();};}
function resumenCarga(ps){
 const c=C.cargaEntregas(ps);
 return `${c.pedidos} ${c.pedidos===1?'pedido':'pedidos'}${c.unidades?` · ${c.unidades} ${c.unidades===1?'unidad':'unidades'}`:''}${c.planchas?` · ${c.planchas} ${c.planchas===1?'plancha':'planchas'}`:''}`;
}
function renderCalendario(){
 const first=mesCalendario+'-01',start=C.inicioSemana(first),hoy=C.fechaHoy(),ps=pedidos().filter(activo);
 $('#contenido').innerHTML=`<div class="panel"><div class="panel-cabecera"><h2>${new Date(first+'T12:00:00Z').toLocaleDateString('es-AR',{month:'long',year:'numeric'})}</h2><div class="fila-acciones"><button class="boton" id="mes-anterior" aria-label="Mes anterior">‹</button><button class="boton" id="mes-actual">Hoy</button><button class="boton" id="mes-siguiente" aria-label="Mes siguiente">›</button></div></div><p class="subtle">Tocá un día para crear un pedido. Para cambiar una entrega, arrastrá el pedido a otro día o usá su flecha.</p><div class="calendario">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(d=>`<div class="dia-titulo">${d}</div>`).join('')}${Array.from({length:42},(_,i)=>{
  const d=C.sumarDias(start,i),delDia=ps.filter(p=>p.entrega===d);
  return `<div data-dia="${d}" class="dia ${d.slice(0,7)!==mesCalendario?'otro':''} ${d===hoy?'actual':''}"><button class="dia-numero" data-nuevo-dia="${d}" aria-label="Nuevo pedido para el ${fecha(d)}" title="Crear pedido para el ${fecha(d)}">${Number(d.slice(-2))}<span aria-hidden="true">＋</span></button>${delDia.length?`<p class="dia-carga">${resumenCarga(delDia)}</p>`:''}${delDia.map(p=>`<div class="pedido-calendario"><button title="Pedido #${p.numero} · ${E(cliente(p).nombre)}" draggable="true" data-arrastrar-pedido="${E(p.id)}" data-pedido="${E(p.id)}" class="${C.indiceEstado(p,config)>=config.estados.length-2?'terminado':''}">#${p.numero} · ${E(cliente(p).nombre)}</button><button class="mover-entrega" data-mover-pedido="${E(p.id)}" aria-label="Reprogramar pedido #${p.numero}" title="Cambiar fecha de entrega">↗</button></div>`).join('')}</div>`;
 }).join('')}</div></div>${ps.some(p=>!p.entrega)?'<div class="panel"><h2>Sin fecha de entrega</h2>'+tablaPedidos(ps.filter(p=>!p.entrega))+'</div>':''}`;
 const move=n=>{const d=new Date(first+'T12:00:00Z');d.setUTCMonth(d.getUTCMonth()+n);mesCalendario=d.toISOString().slice(0,7);render();};
 $('#mes-anterior').onclick=()=>move(-1);$('#mes-siguiente').onclick=()=>move(1);$('#mes-actual').onclick=()=>{mesCalendario=hoy.slice(0,7);render();};bindPedidos();
 $$('[data-nuevo-dia]').forEach(b=>b.onclick=()=>nuevoPedidoPara('',b.dataset.nuevoDia));
 $$('[data-mover-pedido]').forEach(b=>b.onclick=()=>reprogramarPedido(b.dataset.moverPedido));
 let arrastrado=null,finArrastre=0;
 const limpiar=()=>$$('.dia-arrastre').forEach(d=>d.classList.remove('dia-arrastre'));
 $$('[data-arrastrar-pedido]').forEach(b=>{
  b.addEventListener('click',e=>{if(arrastrado||Date.now()-finArrastre<250){e.preventDefault();e.stopImmediatePropagation();}},true);
  b.addEventListener('dragstart',e=>{arrastrado=b.dataset.arrastrarPedido;e.dataTransfer.setData('application/x-waxi-pedido',arrastrado);e.dataTransfer.effectAllowed='move';b.classList.add('arrastrando');});
  b.addEventListener('dragend',()=>{finArrastre=Date.now();arrastrado=null;b.classList.remove('arrastrando');limpiar();});
 });
 $$('[data-dia]').forEach(d=>{
  d.addEventListener('click',e=>{if(e.target===d||e.target.classList.contains('dia-carga'))nuevoPedidoPara('',d.dataset.dia);});
  d.addEventListener('dragover',e=>{if(!arrastrado)return;e.preventDefault();e.dataTransfer.dropEffect='move';limpiar();d.classList.add('dia-arrastre');});
  d.addEventListener('dragleave',e=>{if(!d.contains(e.relatedTarget))d.classList.remove('dia-arrastre');});
  d.addEventListener('drop',e=>{e.preventDefault();limpiar();const id=arrastrado;if(!id||e.dataTransfer.getData('application/x-waxi-pedido')!==id)return;finArrastre=Date.now();arrastrado=null;if(buscar(id)?.entrega!==d.dataset.dia)reprogramarPedido(id,d.dataset.dia);});
 });
}
function reprogramarPedido(id,nuevaFecha){
 const p=buscar(id);if(!p||!activo(p))return;
 abrirModal(cabModal(`Reprogramar pedido #${p.numero}`)+`<p><strong>${E(cliente(p).nombre)}</strong></p><p class="subtle">Entrega actual: ${fecha(p.entrega)}. El cambio quedará en el historial del pedido.</p><form id="form-reprogramar"><div class="campo"><label for="nueva-entrega">Nueva fecha de entrega</label><input id="nueva-entrega" name="entrega" type="date" required value="${E(nuevaFecha||p.entrega||'')}"></div><div class="modal-pie"><button class="boton principal">Confirmar cambio</button></div></form>`);
 
 $('#form-reprogramar').onsubmit=async e=>{
  e.preventDefault();const boton=e.submitter;
  try{const entrega=new FormData(e.target).get('entrega'),actual=buscar(id);if(!actual||!activo(actual))throw Error('Este pedido ya no está pendiente.');if(entrega===actual.entrega){cerrarModal();return;}
   const obj=structuredClone(actual);C.sumarDias(entrega,0);obj.entrega=entrega;obj.historial=[...(obj.historial||[]),{fecha:new Date().toISOString(),texto:`Entrega reprogramada: ${fecha(actual.entrega)} → ${fecha(entrega)}`}];C.validarPedido(obj);if(boton)boton.disabled=true;
   await guardar(obj,'Fecha de entrega actualizada');cerrarModal();
  }catch(err){error(err);}finally{if(boton)boton.disabled=false;}
 };
}
function mostrarCliente(id){
 const c=buscar(id);if(!c)return;
 abrirModal(cabModal(c.nombre)+`<p>${E(c.whatsapp)} · ${E(c.formaEntrega)}<br>${E(c.direccion)}</p><p class="texto-notas">${E(c.notas)}</p><div class="fila-acciones"><button class="boton principal" id="nuevo-pedido-cliente">＋ Nuevo pedido para este cliente</button></div><div class="seccion-formulario"><h3>Historial de pedidos</h3>${tablaPedidos(pedidos().filter(p=>p.cliente===c.id&&!p.anulado))}</div>`);
 $('#nuevo-pedido-cliente').onclick=()=>nuevoPedidoPara(c.id);bindPedidos();
}
function renderClientes(){
 const html=cs=>cs.map(c=>{const ps=pedidos().filter(p=>p.cliente===c.id&&C.confirmado(p,config));return `<div class="cliente-ficha"><div><strong>${E(c.nombre)}</strong><p class="subtle">${E(c.whatsapp)} · ${E(c.formaEntrega)}</p><span class="subtle">${ps.length} compras · ${C.pesos(ps.reduce((s,p)=>s+C.total(p),0))}</span></div><div class="fila-acciones"><button class="boton boton-pequeno" data-nuevo-cliente-pedido="${E(c.id)}">Nuevo pedido</button><button class="boton boton-pequeno" data-cliente="${E(c.id)}">Ver ficha</button><button class="boton boton-pequeno" data-editar-cliente="${E(c.id)}">Editar</button></div></div>`;}).join('')||'<div class="vacio"><strong>No hay clientes para mostrar</strong>Podés crear uno o probar otra búsqueda.</div>';
 $('#contenido').innerHTML=`<div class="panel"><div class="panel-cabecera"><h2>Clientes</h2><button class="boton principal" id="agregar-cliente">＋ Nuevo cliente</button></div><div class="campo"><label class="oculto-visualmente" for="buscar-cliente">Buscar cliente</label><input id="buscar-cliente" type="search" placeholder="Buscar por nombre o WhatsApp"></div><div id="lista-clientes">${html(clientes())}</div></div>`;
 const bind=()=>{$$('[data-editar-cliente]').forEach(b=>b.onclick=()=>formCliente(b.dataset.editarCliente));$$('[data-cliente]').forEach(b=>b.onclick=()=>mostrarCliente(b.dataset.cliente));$$('[data-nuevo-cliente-pedido]').forEach(b=>b.onclick=()=>nuevoPedidoPara(b.dataset.nuevoClientePedido));};
 bind();$('#agregar-cliente').onclick=()=>formCliente();$('#buscar-cliente').oninput=e=>{$('#lista-clientes').innerHTML=html(clientes().filter(c=>C.coincideBusqueda(c.nombre+' '+c.whatsapp,e.target.value)));bind();};
}
function renderProductos(){
 const filas=ps=>ps.map(p=>`<tr><td><strong>${E(p.nombre)}</strong><span class="secundario">${E(p.categoria)}${!p.activo?' · Inactivo':''}</span></td><td>${E(p.unidad)}</td><td>${C.pesos(p.precio)}</td><td>${C.pesos(p.costo)}</td><td><button class="apertura" data-producto="${E(p.id)}">Editar</button></td></tr>`).join('')||'<tr><td colspan="5" class="vacio">No hay productos que coincidan con la búsqueda.</td></tr>';
 $('#contenido').innerHTML=`<div class="panel"><div class="panel-cabecera"><h2>Catálogo de productos</h2><button class="boton principal" id="agregar-producto-catalogo">＋ Nuevo producto</button></div><p class="subtle">Completá tus precios y costos. En cada pedido podés modificarlos.</p><div class="filtros"><div class="campo busqueda"><label for="buscar-producto">Buscar producto</label><input id="buscar-producto" type="search" placeholder="Nombre o categoría"></div><span id="cantidad-productos" class="subtle" role="status"></span></div><div class="tabla-contenedor"><table class="tabla"><thead><tr><th>Producto</th><th>Unidad</th><th>Precio</th><th>Costo</th><th></th></tr></thead><tbody id="lista-productos"></tbody></table></div></div>`;
 const actualizar=()=>{const todos=productos(),ps=todos.filter(p=>C.coincideBusqueda(p.nombre+' '+p.categoria,$('#buscar-producto').value));$('#lista-productos').innerHTML=filas(ps);$('#cantidad-productos').textContent=`${ps.length} de ${todos.length} productos`;$$('[data-producto]').forEach(b=>b.onclick=()=>formProducto(b.dataset.producto));};
 $('#agregar-producto-catalogo').onclick=()=>formProducto();$('#buscar-producto').oninput=actualizar;actualizar();
}
function formProducto(id){const p=id?buscar(id):{nombre:'',categoria:config.categorias[0],unidad:'unidad',precio:0,costo:0,activo:true};abrirModal(cabModal(id?'Editar producto':'Nuevo producto')+`<form id="form-producto"><div class="grilla"><div class="campo ancho"><label for="prod-nombre">Nombre *</label><input id="prod-nombre" name="nombre" required maxlength="180" value="${E(p.nombre)}"></div><div class="campo"><label for="prod-cat">Categoría</label><select id="prod-cat" name="categoria">${opciones(config.categorias,p.categoria)}</select></div><div class="campo"><label for="prod-unidad">Se vende por</label><select id="prod-unidad" name="unidad">${opciones(['unidad','plancha'],p.unidad)}</select></div><div class="campo"><label for="prod-precio">Precio ($)</label><input id="prod-precio" name="precio" type="number" min="0" step="0.01" required value="${p.precio/100}"></div><div class="campo"><label for="prod-costo">Costo ($)</label><input id="prod-costo" name="costo" type="number" min="0" step="0.01" required value="${p.costo/100}"></div><label><input name="activo" type="checkbox" ${p.activo?'checked':''}> Disponible en nuevos pedidos</label></div><div class="modal-pie"><button class="boton principal">Guardar producto</button></div></form>`);$('#form-producto').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));await guardar({tipo:'producto',id:id||crypto.randomUUID(),nombre:f.nombre.trim(),categoria:f.categoria,unidad:f.unidad,precio:C.centavos(f.precio),costo:C.centavos(f.costo),activo:!!f.activo},'Producto guardado');cerrarModal();}catch(err){error(err);}};}
function periodoEstadisticas(){return filtroStats.modo==='mes'?filtroStats.mes:filtroStats.modo==='fechas'?{desde:filtroStats.desde,hasta:filtroStats.hasta}:{};}
function descripcionPeriodo(){
 if(filtroStats.modo==='todo')return 'Todo el historial';
 if(filtroStats.modo==='mes')return new Date(filtroStats.mes+'-01T12:00:00Z').toLocaleDateString('es-AR',{month:'long',year:'numeric'});
 return `${filtroStats.desde?'Desde '+fecha(filtroStats.desde):'Desde el inicio'} · ${filtroStats.hasta?'Hasta '+fecha(filtroStats.hasta):'Hasta la última fecha registrada'}`;
}
function renderEstadisticas(){
 const s=C.estadisticas(pedidos(),config,periodoEstadisticas()),totalHistorico=filtroStats.modo==='todo';
 let comparacion='';
 if(filtroStats.modo==='mes'){
  const d=new Date(filtroStats.mes+'-01T12:00:00Z');d.setUTCMonth(d.getUTCMonth()-1);const previo=C.estadisticas(pedidos(),config,d.toISOString().slice(0,7));
  comparacion=`<div class="panel"><h2>Comparación con el mes anterior</h2>${[['Ventas',s.vendido,previo.vendido],['Cobros',s.ingresos,previo.ingresos],['Ganancia',s.ganancia,previo.ganancia]].map(([t,n,old])=>`<div class="desglose"><div>${t}<span class="subtle" style="display:block">Antes: ${C.pesos(old)}</span></div><strong>${old?((n-old)/Math.abs(old)*100).toFixed(1)+'%':n?'Sin base anterior':'—'}</strong></div>`).join('')}</div>`;
 }
 const indicadores=[['Ventas confirmadas',s.vendido],[totalHistorico?'Cobrado total':'Cobrado en el período',s.ingresos],['Ganancia estimada',s.ganancia],['Ticket promedio',s.ticket]];
 $('#contenido').innerHTML=`<form id="form-periodo-estadisticas" class="filtros"><div class="campo filtro-periodo"><label for="tipo-periodo-estadisticas">Período</label><select id="tipo-periodo-estadisticas" name="modo">${opciones([{id:'todo',nombre:'Total histórico'},{id:'mes',nombre:'Por mes'},{id:'fechas',nombre:'Por fechas'}],filtroStats.modo)}</select></div><div class="campo" id="campo-mes-estadisticas" ${filtroStats.modo!=='mes'?'hidden':''}><label for="mes-estadisticas">Mes</label><input id="mes-estadisticas" name="mes" type="month" value="${E(filtroStats.mes)}" ${filtroStats.modo==='mes'?'required':''}></div><div class="rango-estadisticas" id="campo-fechas-estadisticas" ${filtroStats.modo!=='fechas'?'hidden':''}><div class="campo"><label for="desde-estadisticas">Desde</label><input id="desde-estadisticas" name="desde" type="date" value="${E(filtroStats.desde)}"></div><div class="campo"><label for="hasta-estadisticas">Hasta</label><input id="hasta-estadisticas" name="hasta" type="date" value="${E(filtroStats.hasta)}"></div></div><button class="boton principal">Aplicar</button>${!totalHistorico?'<button type="button" class="boton" id="total-historico-estadisticas">Ver total histórico</button>':''}</form><p class="subtle" id="periodo-estadisticas" role="status">${E(descripcionPeriodo())}</p><div class="resumen">${indicadores.map(([t,n])=>`<div class="indicador"><span class="texto">${t}</span><span class="valor" style="font-size:1.5rem">${C.pesos(n)}</span></div>`).join('')}</div><div class="${comparacion?'comparacion':'resumen-estadisticas'}"><div class="panel"><h2>${totalHistorico?'Resumen histórico':'Resumen del período'}</h2>${[['Pedidos confirmados',s.cantidad],['Costos estimados',C.pesos(s.costos)],['Descuentos',C.pesos(s.descuentos)],['Margen estimado',s.vendido?(100*s.ganancia/s.vendido).toFixed(1)+'%':'—'],[totalHistorico?'Saldo pendiente actual':'Saldo actual de pedidos del período',C.pesos(s.pendiente)]].map(([t,n])=>`<div class="desglose"><span>${t}</span><strong>${n}</strong></div>`).join('')}<p class="subtle">Ventas por fecha de confirmación y cobros por fecha del pago. El saldo usa lo que falta cobrar hoy de los pedidos confirmados en el período. Ganancia = venta − costo de productos; no incluye gastos generales. Presupuestos, posibles pedidos y anulados quedan fuera.</p></div>${comparacion}</div>${s.canales.length?`<div class="panel"><h2>Ventas por canal</h2><div class="barras">${s.canales.map(c=>`<div class="barra"><span>${E(c.canal)}</span><div class="pista"><div class="relleno" style="width:${Math.max(1,c.total/s.vendido*100)}%"></div></div><strong>${C.pesos(c.total)}</strong></div>`).join('')}</div></div>`:''}<div class="panel"><div class="panel-cabecera"><h2>Estadísticas de todos los productos</h2><span class="subtle" id="cantidad-productos-estadisticas" role="status"></span></div><p class="subtle">Ordenados por cantidad vendida, de mayor a menor. Incluye productos sin ventas e inactivos. Cantidades y facturación de pedidos confirmados ${totalHistorico?'en todo el historial':'en el período seleccionado'}; los descuentos se reparten proporcionalmente entre sus productos.</p><div class="filtros"><div class="campo busqueda"><label for="buscar-producto-estadisticas">Buscar producto en estadísticas</label><input type="search" id="buscar-producto-estadisticas" placeholder="Nombre del producto" value="${E(busquedaStats)}"></div></div><div class="tabla-contenedor"><table class="tabla" id="tabla-estadisticas-productos"><thead><tr><th>Producto</th><th>Cantidad vendida</th><th>Pedidos</th><th>Facturación</th></tr></thead><tbody></tbody><tfoot><tr><th colspan="3">${totalHistorico?'Total histórico':'Total del período'} · todos los productos</th><td class="importe">${C.pesos(s.vendido)}</td></tr></tfoot></table></div></div>`;
 renderEstadisticasProductos();$('#buscar-producto-estadisticas').oninput=e=>{busquedaStats=e.target.value;renderEstadisticasProductos();};
 $('#tipo-periodo-estadisticas').onchange=e=>{const modo=e.target.value;$('#campo-mes-estadisticas').hidden=modo!=='mes';$('#mes-estadisticas').required=modo==='mes';$('#campo-fechas-estadisticas').hidden=modo!=='fechas';};
 $('#form-periodo-estadisticas').onsubmit=e=>{
  e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));if(f.modo==='mes'&&!f.mes)throw Error('Elegí un mes.');if(f.modo==='fechas'&&!f.desde&&!f.hasta)throw Error('Completá al menos una fecha.');
   C.limitesEstadisticas(f.modo==='mes'?f.mes:f.modo==='fechas'?{desde:f.desde,hasta:f.hasta}:{});filtroStats={modo:f.modo,mes:f.mes,desde:f.desde,hasta:f.hasta};renderEstadisticas();
  }catch(err){error(err);}
 };
 $('#total-historico-estadisticas')?.addEventListener('click',()=>{filtroStats.modo='todo';renderEstadisticas();});
}
function renderEstadisticasProductos(){
 const todas=C.estadisticasProductos(pedidos(),config,periodoEstadisticas(),productos()),consulta=$('#buscar-producto-estadisticas').value,filas=todas.filter(p=>C.coincideBusqueda(p.nombre,consulta));
 $('#cantidad-productos-estadisticas').textContent=`${filas.length} de ${todas.length} productos`;
 $('#tabla-estadisticas-productos tbody').innerHTML=filas.map(p=>`<tr data-estadistica-producto="${E(p.id)}"><td><strong>${E(p.nombre)}</strong>${!p.activo?'<span class="secundario">Inactivo / histórico</span>':''}</td><td>${p.cantidad} ${p.unidad==='plancha'?(p.cantidad===1?'plancha':'planchas'):(p.cantidad===1?'unidad':'unidades')}</td><td>${p.pedidos}</td><td class="importe">${C.pesos(p.facturacion)}</td></tr>`).join('')||'<tr><td colspan="4" class="vacio">No hay productos que coincidan con la búsqueda.</td></tr>';
}
async function renderConfiguracion(){const conn=(await S.meta('conexion'))?.value,copias=await S.listarCopias();if(vista!=='configuracion')return;$('#contenido').innerHTML=`<div class="panel"><h2>Waxi y documentos</h2><form id="form-config"><div class="grilla"><div class="campo"><label for="negocio">Nombre del negocio</label><input id="negocio" name="negocio" required value="${E(config.negocio)}"></div><div class="campo"><label for="contacto">Contacto en presupuestos</label><input id="contacto" name="contacto" placeholder="WhatsApp, Instagram o web" value="${E(config.contacto)}"></div><div class="campo ancho"><label for="notas-documento">Texto al pie del presupuesto</label><textarea id="notas-documento" name="notasDocumento" placeholder="Condiciones de pago o aclaraciones">${E(config.notasDocumento)}</textarea></div><div class="campo"><label for="categorias">Categorías (una por línea)</label><textarea id="categorias" name="categorias">${E(config.categorias.join('\n'))}</textarea></div><div class="campo"><label for="etiquetas">Etiquetas (una por línea)</label><textarea id="etiquetas" name="etiquetas">${E(config.etiquetas.join('\n'))}</textarea></div><div class="campo"><label for="canales">Canales de venta (uno por línea)</label><textarea id="canales" name="canales">${E(config.canales.join('\n'))}</textarea></div></div><div class="modal-pie"><button class="boton principal">Guardar configuración</button></div></form></div><div class="panel"><div class="panel-cabecera"><h2>Estados de producción</h2><button class="boton" id="nuevo-estado">＋ Agregar estado</button></div><p class="subtle">El primero es Posible pedido y el último es Entregado. El estado general usa el producto con menor avance.</p><div id="estados-config">${config.estados.map((s,i)=>`<div class="estado-edicion"><span class="ordinal">${i+1}</span><input class="control" aria-label="Nombre del estado ${i+1}" data-nombre-estado="${E(s.id)}" value="${E(s.nombre)}"><button class="boton boton-pequeno" data-eliminar-estado="${E(s.id)}" ${i===0||i===1||i===config.estados.length-1?'disabled':''}>Quitar</button></div>`).join('')}</div><button class="boton" id="guardar-estados">Guardar nombres</button></div><div class="panel"><h2>Sincronización y dispositivos</h2><p class="subtle">${conn?'La conexión está configurada. Los cambios se sincronizan al recuperar internet.':'Los datos se guardan en este navegador. PC y celular todavía no están conectados. Antes de usarla en ambos, activá la conexión.'}</p><form id="form-conexion"><div class="grilla"><div class="campo"><label for="url-conexion">Dirección del servicio</label><input id="url-conexion" type="url" name="url" placeholder="https://…workers.dev" value="${E(conn?.url||'')}" required></div><div class="campo"><label for="clave-conexion">Clave privada de conexión</label><input id="clave-conexion" type="password" name="clave" required minlength="32" autocomplete="off" value="${E(conn?.clave||'')}"><small>Se guarda solo en este dispositivo. Nunca en GitHub.</small></div></div><div class="modal-pie"><button class="boton principal">Conectar</button>${conn?'<button type="button" class="boton" id="enlazar-dispositivo">Conectar otro dispositivo</button><button type="button" class="boton" id="desconectar">Desconectar</button>':''}</div></form></div><div class="panel"><h2>Recordatorios</h2><p class="subtle">Pedidos atrasados, entregas de hoy y mañana, y pedidos sin avance durante ${config.diasSinAvance} días. Los avisos externos requieren la conexión y el permiso del navegador.</p><div class="fila-acciones"><button class="boton" id="activar-avisos">Activar notificaciones</button><button class="boton" id="ver-avisos">Ver recordatorios</button><span id="estado-avisos" class="subtle"></span></div></div><div class="panel"><h2>Recuperación</h2><p class="subtle">Copia diaria en este dispositivo, conservada durante siete días. Si borrás los datos del navegador, también se pierden estas copias. Los pedidos permiten deshacer su último cambio.</p>${copias.length?`<div class="fila-acciones"><label for="copia" class="oculto-visualmente">Copia a recuperar</label><select id="copia" class="control" style="max-width:200px">${opciones(copias.map(c=>({id:c.id,nombre:fecha(c.id)})))}</select><button class="boton" id="restaurar-copia">Restaurar copia</button></div>`:''}</div>`;
 $('#form-config').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target));const lineas=k=>[...new Set(f[k].split('\n').map(x=>x.trim()).filter(Boolean))];if(!lineas('categorias').length||!lineas('canales').length)throw Error('Mantené al menos una categoría y un canal.');await guardar({...config,negocio:f.negocio.trim(),contacto:f.contacto.trim(),notasDocumento:f.notasDocumento.trim(),categorias:lineas('categorias'),etiquetas:lineas('etiquetas'),canales:lineas('canales')},'Configuración guardada');}catch(err){error(err);}};
 $('#guardar-estados').onclick=async()=>{const estados=config.estados.map(s=>({...s,nombre:$(`[data-nombre-estado="${s.id}"]`).value.trim()}));if(estados.some(s=>!s.nombre)||new Set(estados.map(s=>s.nombre)).size!==estados.length)return error('Los estados deben tener nombres diferentes.');await guardar({...config,estados},'Estados guardados');};$('#nuevo-estado').onclick=async()=>{const nombre=prompt('Nombre del nuevo estado (se ubicará antes de Terminado):');if(!nombre?.trim())return;if(config.estados.some(s=>s.nombre===nombre.trim()))return error('Ya existe ese estado.');const estados=[...config.estados];estados.splice(estados.length-2,0,{id:crypto.randomUUID(),nombre:nombre.trim()});await guardar({...config,estados},'Estado agregado');};$$('[data-eliminar-estado]').forEach(b=>b.onclick=async()=>{const id=b.dataset.eliminarEstado;if(pedidos().some(p=>p.items.some(i=>i.estado===id)))return error('Este estado está usado por pedidos. Cambiá sus productos de estado primero.');if(!confirm('¿Quitar este estado?'))return;await guardar({...config,estados:config.estados.filter(s=>s.id!==id)},'Estado eliminado');});
 $('#form-conexion').onsubmit=async e=>{e.preventDefault();try{const f=Object.fromEntries(new FormData(e.target)),url=new URL(f.url);if(url.protocol!=='https:')throw Error('La conexión requiere una dirección HTTPS.');if(url.username||url.password||url.search||url.hash)throw Error('Usá solo la dirección HTTPS del servicio.');if(f.clave.length<32)throw Error('La clave debe tener al menos 32 caracteres.');await S.guardarMeta('conexion',{url:url.origin+url.pathname.replace(/\/$/,''),clave:f.clave});await sincronizar(true);render();}catch(err){error(err);}};$('#desconectar')?.addEventListener('click',async()=>{if(!confirm('¿Desconectar la sincronización? Los datos seguirán en este dispositivo.'))return;await S.guardarMeta('conexion',null);render();$('#conexion').textContent='Guardado en este dispositivo';});$('#enlazar-dispositivo')?.addEventListener('click',async()=>{const link=new URL(location.href);link.hash='connect='+btoa(unescape(encodeURIComponent(JSON.stringify(conn))));abrirModal(cabModal('Conectar otro dispositivo')+`<p>Este enlace permite acceder a tus pedidos. Abrilo únicamente en tus dispositivos.</p><div class="campo"><label for="enlace-privado">Enlace privado</label><textarea id="enlace-privado" readonly>${E(link.href)}</textarea></div><div class="modal-pie"><button class="boton" id="copiar-enlace">Copiar enlace</button></div>`);$('#copiar-enlace').onclick=async()=>{try{await navigator.clipboard.writeText(link.href);toast('Enlace copiado');}catch{error('Seleccioná y copiá el enlace.');}};});$('#activar-avisos').onclick=activarAvisos;$('#ver-avisos').onclick=mostrarAvisos;$('#restaurar-copia')?.addEventListener('click',async()=>{if(!confirm('¿Restaurar esta copia? Se reemplazarán los datos actuales de este dispositivo y se enviarán los cambios a la nube si está conectada.'))return;await S.restaurarCopia($('#copia').value);await cargar();render();toast('Copia restaurada');sincronizar();});}
async function sincronizar(mostrar=false){try{const result=await S.sincronizar();if(result.estado==='ok'||result.estado==='conflicto'){await cargar();if(!$('#modal').open)render();}$('#conexion').textContent=({local:'Guardado en este dispositivo',offline:navigator.onLine?'Sincronizando…':'Sin conexión · guardado local',ok:'Sincronizado',conflicto:'Cambios para revisar'})[result.estado];if(mostrar&&result.estado==='ok')toast('Dispositivos conectados');}catch(e){$('#conexion').textContent='Sin sincronizar · guardado local';if(mostrar)error(e);}}
function mostrarConflictos(){const conflicts=datos.filter(e=>e._conflicto);abrirModal(cabModal('Revisar cambios')+`<p>Ambos dispositivos cambiaron el mismo registro. Elegí qué versión conservar.</p>${conflicts.map(e=>`<div class="panel"><h3>${E(e.nombre||'#'+e.numero||e.id)}</h3><div class="comparacion"><div><strong>Este dispositivo</strong><pre class="texto-notas">${E(JSON.stringify(S.limpio(e),null,2))}</pre><button class="boton" data-conflicto="${E(e.id)}" data-local="1">Conservar esta versión</button></div><div><strong>Otro dispositivo</strong><pre class="texto-notas">${E(JSON.stringify(e._conflicto.datos,null,2))}</pre><button class="boton" data-conflicto="${E(e.id)}" data-local="0">Conservar versión remota</button></div></div></div>`).join('')}`);$$('[data-conflicto]').forEach(b=>b.onclick=async()=>{await S.resolverConflicto(b.dataset.conflicto,b.dataset.local==='1');await cargar();cerrarModal();render();sincronizar();});}
function mostrarAvisos(){const ps=recordatorios();abrirModal(cabModal('Recordatorios')+(ps.length?tablaPedidos(ps):'<p>No hay entregas próximas ni pedidos sin avance.</p>'));bindPedidos();}
async function activarAvisos(){try{if(!('Notification'in window)||!('serviceWorker'in navigator)||!('PushManager'in window))throw Error('Este navegador no admite notificaciones web.');const conn=(await S.meta('conexion'))?.value;if(!conn)throw Error('Conectá la sincronización antes de activar avisos con la app cerrada.');const permission=await Notification.requestPermission();if(permission!=='granted')throw Error('El navegador no autorizó las notificaciones. Revisá los permisos del sitio.');const res=await fetch(conn.url+'/push-key',{headers:{Authorization:'Bearer '+conn.clave}});if(!res.ok)throw Error('Los avisos todavía no están configurados en el servicio.');const {publicKey}=await res.json();if(!publicKey)throw Error('Los avisos todavía no están configurados en el servicio.');const reg=await navigator.serviceWorker.ready;const applicationServerKey=Uint8Array.from(atob(publicKey.replace(/-/g,'+').replace(/_/g,'/')),c=>c.charCodeAt(0));const sub=await reg.pushManager.getSubscription()||await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey});const response=await fetch(conn.url+'/subscription',{method:'POST',headers:{'Content-Type':'application/json',Authorization:'Bearer '+conn.clave},body:JSON.stringify(sub)});if(!response.ok)throw Error('No se pudo registrar el dispositivo.');toast('Recordatorios activados para este dispositivo');if($('#estado-avisos'))$('#estado-avisos').textContent='Activados';}catch(e){error(e);}}
$('#nuevo').onclick=()=>formPedido();$('#modal').addEventListener('cancel',e=>e.preventDefault());window.addEventListener('hashchange',()=>{filtros={};render();});window.addEventListener('online',()=>sincronizar());window.addEventListener('offline',()=>$('#conexion').textContent='Sin conexión · guardado local');window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();instalable=e;$('#instalar').hidden=false;});$('#instalar').onclick=async()=>{await instalable.prompt();$('#instalar').hidden=true;};
try{await S.abrir();if(location.hash.startsWith('#connect=')){const raw=JSON.parse(decodeURIComponent(escape(atob(location.hash.slice(9)))));const u=new URL(raw.url);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash||typeof raw.clave!=='string'||raw.clave.length<32)throw Error('El enlace de conexión no es válido.');if(confirm('¿Conectar este dispositivo a tus pedidos Waxi?'))await S.guardarMeta('conexion',{url:u.origin+u.pathname.replace(/\/$/,''),clave:raw.clave});history.replaceState(null,'',location.pathname+'#pedidos');}await cargar();render();if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});await sincronizar();setInterval(()=>{if(!document.hidden)sincronizar();S.copiaDiaria().catch(()=>{});},30000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)sincronizar();});}catch(e){$('#contenido').innerHTML=`<div class="aviso error">No se pudo abrir el guardado local: ${E(e.message)}. Revisá que el navegador permita almacenar datos.</div>`;}
